/** @jsxImportSource solid-js */
import { onMount, onCleanup, createEffect } from "solid-js";
import { mountBackToTopRocket, type BackToTopRocketOptions } from "../../components/back-to-top-rocket/BackToTopRocketEngine.js";
import type { MotionController } from "../../components/back-to-top-rocket/motion-runtime";

export function BackToTopRocket(props: { options?: BackToTopRocketOptions; class?: string }) {
  let host!: HTMLDivElement;
  let controller: MotionController | undefined;
  onMount(() => { controller = mountBackToTopRocket(host, props.options); });
  createEffect(() => { const options = props.options; controller?.update(options ?? {}); });
  onCleanup(() => controller?.destroy());
  return <div ref={host} class={props.class} data-motion-component="back-to-top-rocket" />;
}

